// 微信数据审计
async function fetchWechatData() {
  const out = document.getElementById('wechat-out');
  out.textContent = '正在读取本地解密数据库...\n';
  try {
    const res = await fetch(`${GATEWAY_URL}/api/wechat/openclaw/messages`);
    const data = await res.json();
    out.textContent = `[成功] 发现 ${data.length} 条高价值新对话线索：\n` + 
      data.map((m, i) => `${i+1}. ${m.from_user}: "${m.content.substring(0,25)}..."`).join('\n');
  } catch (err) {
    out.textContent = `[错误] 本地网关未启动。请先在终端运行 npm start。\n${err.message}`;
  }
}
